WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_text_single_para'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '单段文字', 'kp-xingce-data-text-single-para', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "单段文字"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "数据密度极高的一整段文字，不分段，容易产生视觉疲劳。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "整篇材料只有一段，却包含了十几个甚至几十个数据。极容易看串行。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "用标点符号“切豆腐”，把一整段强行切成独立的意群。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[拿到单段长文] --> B[手里拿笔开始找标点]\nB --> C[遇到句号'。']\nC --> D[在句号处划一条重重的竖线, 把段落切断]\nB --> E[遇到分号'；']\nE --> F[在分号下面画波浪线, 提醒自己这里是并列项]\nD --> G[开始做题, 根据题干主体直接跳入对应的被切断的'豆腐块'找数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【材料】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年...增加值2345亿元，增长5.4%。规模以上工业中，国有企业...；股份制企业...；外商投资企业...。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "切分：在“增长5.4%。”后面划竖线。前半截讲总盘子。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找并列：在三个“；”处标注。后半截讲企业分类。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "做题定位：题目问“外商投资企业”，直接越过前半截，在最后的并列项里去找。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "串行找错数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目问 A 企业的量，你眼睛盯着 A 企业的名字，却顺手抄了紧跟在后面的 B 企业的数字。切分豆腐块就是为了限制视线滑动范围。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到单段长文，强制要求自己动笔切分。不要过度自信自己的眼球追踪能力。"}]}]}$$ AS jsonb), NULL, '单段文字的核心读题与防坑技巧。', category_node.id, CAST('["资料分析", "单段文字"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_text_single_para", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
